/**
 * Writes the OpenUI half of the Agent's system prompt into `internal/agent/openui/openui.json`.
 *
 * The Go runtime owns the prompt, but the prompt is the official OpenUI one: generated by
 * `@openuidev/assistant-ui` from the official chat library, the OMC prompt options in
 * `web/src/agent/openui/prompt.ts`, and the capability catalogue the Go registry exported to
 * `internal/agent/openui/capabilities.json` (`TestOpenUICapabilityCatalogue`). Generating it here
 * rather than writing it by hand keeps the vocabulary the model is taught equal to the one the
 * console renders; `--check` fails when the committed file is stale, after an OpenUI upgrade, a
 * prompt-option edit or a catalogue change.
 *
 * Run it with `pnpm openui:prompt`; `pnpm check:openui-prompt` is the staleness check.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { omcOpenUIInstructions, PARAMETER_DESCRIPTION, PRESENT_TOOL, PROMPT_TOOL, TOOL_DESCRIPTIONS } from '../web/src/agent/openui/prompt.ts';
import type { OpenUICapability } from '../web/src/agent/openui/prompt.ts';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const directory = path.join(root, 'internal/agent/openui');
const target = path.join(directory, 'openui.json');

const capabilities = JSON.parse(fs.readFileSync(path.join(directory, 'capabilities.json'), 'utf8')) as OpenUICapability[];
if (PRESENT_TOOL !== 'present_openui' || PROMPT_TOOL !== 'prompt_openui') {
  // The Go runtime names the tools; a renamed official default must be followed there first.
  throw new Error(`OpenUI tool names changed to ${PRESENT_TOOL} / ${PROMPT_TOOL}; update internal/agent/openui.go`);
}
const generated = `${JSON.stringify({
  instructions: omcOpenUIInstructions(capabilities),
  present_description: TOOL_DESCRIPTIONS.present,
  prompt_description: TOOL_DESCRIPTIONS.prompt,
  parameter_description: PARAMETER_DESCRIPTION,
}, null, 2)}\n`;

if (process.argv.includes('--check')) {
  const committed = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : '';
  if (committed !== generated) {
    console.error('internal/agent/openui/openui.json is stale: run pnpm openui:prompt and commit the result.');
    process.exit(1);
  }
} else {
  fs.writeFileSync(target, generated);
  console.log(`wrote ${path.relative(root, target)} (${generated.length} bytes)`);
}
